#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-24

# Installs the built bundle into ~/Applications and restarts it.
# The login item registers against the bundle's PATH, and `build-app.sh` does
# `rm -rf dist/`, so the live copy must NOT be the build output.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Must match build-app.sh. See there for the rename rationale.
APP_NAME="Tower"
SRC="$ROOT/dist/$APP_NAME.app"
# Test hook: scripts/test-install.sh points this inside its sandbox, so every
# destination side effect stays sandboxed even if a PATH mock is dropped and
# the real rm, cp or find runs (issue #39). Unset means the user destination.
DEST_DIR="${TOWER_TEST_INSTALLED:-$HOME/Applications}"
DEST="$DEST_DIR/$APP_NAME.app"
ARCHIVE_NAME="$APP_NAME.app.zip"
CHECKSUM_NAME="$ARCHIVE_NAME.sha256"
# Forks set TOWER_REPOSITORY=<owner>/<repo> to install from their own builds.
REPOSITORY="${TOWER_REPOSITORY:-yonatangross/tower}"
DOWNLOAD_DIR=""

usage() {
  echo "Usage: scripts/install.sh [--from-artifact | --from-release <tag>]" >&2
  echo "  TOWER_INSTALL_FROM=artifact with no arguments selects the artifact path (update.sh uses this)" >&2
}

cleanup_download() {
  if [ -n "$DOWNLOAD_DIR" ] && [ -d "$DOWNLOAD_DIR" ]; then
    rm -rf "$DOWNLOAD_DIR"
  fi
}
trap cleanup_download EXIT

fail() {
  echo "$*" >&2
  exit 1
}

download_dir() {
  DOWNLOAD_DIR="$(mktemp -d "${TMPDIR:-/tmp}/tower-install.XXXXXX")"
}

download_from_artifact() {
  local run_id artifact_name

  run_id="$(gh api "repos/$REPOSITORY/actions/workflows/release-app.yml/runs?branch=main&event=push&status=success&per_page=1" --jq '.workflow_runs[0].id // empty')"
  [ -n "$run_id" ] || fail "No successful main release-app workflow run was found."

  # first() inside the jq expression, NOT a trailing `| head -n 1`: head
  # closes the pipe early, gh can die on SIGPIPE, and under pipefail that
  # aborts the script with status 141 and no message the moment a run carries
  # a second matching artifact. Mirrored in update.sh; keep the two in sync.
  artifact_name="$(gh api "repos/$REPOSITORY/actions/runs/$run_id/artifacts?per_page=100" -q 'first(.artifacts[] | select(.expired == false) | select(.name | startswith("tower-app-")) | .name) // empty')"
  [ -n "$artifact_name" ] || fail "No unexpired Tower artifact was found for workflow run $run_id."

  gh run download "$run_id" --repo "$REPOSITORY" --name "$artifact_name" --dir "$DOWNLOAD_DIR"
}

download_from_release() {
  local tag="$1"
  gh release download "$tag" --repo "$REPOSITORY" --pattern "$ARCHIVE_NAME" --pattern "$CHECKSUM_NAME" --dir "$DOWNLOAD_DIR"
}

verify_and_unpack() {
  local archive_path checksum_path checksum_lines checksum_fields expected_name expected_hash actual_hash

  archive_path="$DOWNLOAD_DIR/$ARCHIVE_NAME"
  checksum_path="$DOWNLOAD_DIR/$CHECKSUM_NAME"
  [ -f "$archive_path" ] || fail "Downloaded archive is missing: $ARCHIVE_NAME"
  [ -f "$checksum_path" ] || fail "Downloaded checksum is missing: $CHECKSUM_NAME"

  checksum_lines="$(awk 'END { print NR }' "$checksum_path")"
  checksum_fields="$(awk 'NR == 1 { print NF }' "$checksum_path")"
  expected_hash="$(awk 'NR == 1 { print $1 }' "$checksum_path")"
  expected_name="$(awk 'NR == 1 { print $2 }' "$checksum_path")"
  if [ "$checksum_lines" != 1 ] || [ "$checksum_fields" != 2 ] || [ "$expected_name" != "$ARCHIVE_NAME" ]; then
    fail "Checksum manifest must contain exactly one entry for $ARCHIVE_NAME."
  fi

  actual_hash="$(shasum -a 256 "$archive_path" | awk '{ print $1 }')"
  if [ "$actual_hash" != "$expected_hash" ]; then
    fail "SHA-256 verification failed for $ARCHIVE_NAME."
  fi

  mkdir -p "$DOWNLOAD_DIR/unpacked"
  ditto -x -k "$archive_path" "$DOWNLOAD_DIR/unpacked"
  SRC="$DOWNLOAD_DIR/unpacked/$APP_NAME.app"
}

# What to install. argv wins; with no arguments TOWER_INSTALL_FROM may name the
# source so programmatic callers (scripts/update.sh) are not tied to flag
# spelling. Empty means the local build at $SRC.
install_source=""
release_tag=""
case "$#" in
  0)
    case "${TOWER_INSTALL_FROM:-}" in
      "") ;;
      artifact) install_source="artifact" ;;
      *) fail "unknown TOWER_INSTALL_FROM: $TOWER_INSTALL_FROM" ;;
    esac
    ;;
  1)
    if [ "$1" != "--from-artifact" ]; then
      usage
      exit 2
    fi
    install_source="artifact"
    ;;
  2)
    if [ "$1" != "--from-release" ] || [ -z "$2" ]; then
      usage
      exit 2
    fi
    install_source="release"
    release_tag="$2"
    ;;
  *)
    usage
    exit 2
    ;;
esac

case "$install_source" in
  "") ;;
  artifact)
    download_dir
    download_from_artifact
    verify_and_unpack
    ;;
  release)
    download_dir
    download_from_release "$release_tag"
    verify_and_unpack
    ;;
esac

if [ ! -d "$SRC" ]; then
  echo "No build at $SRC. Run scripts/build-app.sh first." >&2
  exit 1
fi

# "Tower" is also the executable of an unrelated Git client, so nothing here
# matches the bare name: the process pattern is anchored to this install's path,
# and a Tower.app at DEST that carries another bundle id is never replaced.
# Before v0.1 the executable was HQClaudeLimits (bundle id
# ai.yonatan-hq.claude-limits); that name is unique, so it still matches anywhere.
PROCESS_PATTERN="$DEST/Contents/MacOS/(Tower|HQClaudeLimits)( |\$)"
if [ -f "$DEST/Contents/Info.plist" ]; then
  existing_id="$(plutil -extract CFBundleIdentifier raw "$DEST/Contents/Info.plist" 2>/dev/null)" || existing_id="unreadable"
  case "$existing_id" in
    ai.yonyon.tower|ai.yonyon.tower.*|ai.yonatan-hq.claude-limits|ai.yonatan-hq.claude-limits.*) ;;
    *) fail "$DEST belongs to another app (bundle id $existing_id). Move it, then run this again." ;;
  esac
fi

echo "==> stopping any running instance"
# pkill exits 1 when nothing matched, which is the normal first-install case.
# Any other exit code is a real failure and is surfaced.
for pattern in "/Contents/MacOS/HQClaudeLimits( |\$)" "$PROCESS_PATTERN"; do
  rc=0
  pkill -f "$pattern" || rc=$?
  if [ "$rc" -gt 1 ]; then
    echo "pkill failed with exit $rc" >&2
    exit "$rc"
  fi
done

# An install that still runs the pre-v0.1 executable registered its login item
# under the old bundle id. Ask the old binary whether it is on, switch it off
# there, and switch it on for the new id after the copy, so the setting carries
# over and no stale registration is left behind.
legacy_login=0
LEGACY_EXE="$DEST/Contents/MacOS/HQClaudeLimits"
if [ -x "$LEGACY_EXE" ]; then
  legacy_status="$("$LEGACY_EXE" login-item 2>/dev/null)" || legacy_status=""
  case "$legacy_status" in
    *ENABLED*)
      legacy_login=1
      echo "==> moving start-at-login from the pre-v0.1 build"
      "$LEGACY_EXE" login-item off >/dev/null 2>&1 || echo "   WARNING: could not switch the old login item off" >&2
      ;;
  esac
fi

mkdir -p "$DEST_DIR"
echo "==> installing to $DEST"
rm -rf "$DEST"
cp -R "$SRC" "$DEST"

# #121: a downloaded bundle is ad-hoc signed by CI, a new signature per build, so the
# Tower-owned seat items the previous build wrote would refuse it and every retained seat
# would read "needs login" after an update. Re-sign it with this machine's "Tower Dev"
# identity, the one build-app.sh uses, before it first runs. Without the identity the
# artifact keeps its ad-hoc signature. A local build is already signed by build-app.sh.
if [ -n "$install_source" ]; then
  # shellcheck source=scripts/sign-app.sh
  . "$ROOT/scripts/sign-app.sh"
  tower_sign_app "$DEST" no
fi

# RENAME MIGRATION. SMAppService registers a bundle PATH, so renaming the app
# leaves the previous bundle on disk STILL registered at login: the next reboot
# launches the stale binary, and every fix in the new one silently vanishes.
# Identify siblings by the EXECUTABLE, not the folder name - the name is exactly
# what changed. Renames so far: "HQ Claude Limits" -> "Limits" -> "Tower".
#
# SUPERSEDES the LEGACY_APP_NAME="HQ Claude Limits" special case this replaced.
# That hardcoded exactly one previous name, so it went stale the moment a SECOND
# rename happened: on the Limits -> Tower move it would have cleaned up a bundle
# that was already gone and left the actual stale one, Limits.app, registered at
# login. Matching on the executable needs no list and cannot go stale.
#
# #14: a sibling is never deleted. A copy under one of the names Tower shipped as
# (Limits, HQ Claude Limits) is a leftover of a rename: it moves aside to
# $DEST_DIR/.tower-replaced/<name>-<stamp>.app. Any other name was chosen by the
# user (a rollback copy such as Tower-c73b9ed.app), so it stays where it is and is
# only reported. Either way its login item is turned off first, so the next login
# cannot start the old binary.
REPLACED_DIR="$DEST_DIR/.tower-replaced"
SHIPPED_NAMES=("Limits.app" "HQ Claude Limits.app")

is_shipped_name() {
  local name="$1" shipped
  for shipped in "${SHIPPED_NAMES[@]}"; do
    [ "$name" = "$shipped" ] && return 0
  done
  return 1
}

# Prints a path under REPLACED_DIR that does not exist yet.
replaced_path() {
  local base="$1" stamp candidate n=1
  stamp="$(date +%Y%m%d-%H%M%S)"
  candidate="$REPLACED_DIR/${base%.app}-$stamp.app"
  while [ -e "$candidate" ]; do
    n=$((n + 1))
    candidate="$REPLACED_DIR/${base%.app}-$stamp-$n.app"
  done
  printf '%s\n' "$candidate"
}

migrated=0
while IFS= read -r stale; do
  [ "$stale" = "$DEST" ] && continue
  migrated=1
  name="$(basename "$stale")"
  # Bounded: the first pre-v0.1 builds have no login-item verb, so the binary would
  # start the old menubar app instead and never return. perl's alarm ends it.
  if ! perl -e 'alarm shift; exec @ARGV or exit 127' "${TOWER_SIBLING_TIMEOUT:-10}" \
       "$stale/Contents/MacOS/HQClaudeLimits" login-item off; then
    echo "   WARNING: could not turn off the login item of $stale (no answer or no login-item verb)" >&2
  fi
  if is_shipped_name "$name"; then
    mkdir -p "$REPLACED_DIR"
    target="$(replaced_path "$name")"
    mv "$stale" "$target"
    echo "==> moved stale bundle aside: $stale -> $target"
  else
    echo "==> kept $stale (a name you chose); its login item is off. Delete it yourself when you no longer need it."
  fi
done < <(find "$DEST_DIR" -maxdepth 1 -name '*.app' \
           -exec test -f '{}/Contents/MacOS/HQClaudeLimits' \; -print)

echo "==> launching"
open "$DEST"
sleep 3

if pgrep -f "$DEST/Contents/MacOS/Tower( |\$)" >/dev/null; then
  echo "Running from $DEST"
else
  echo "WARNING: app did not stay running" >&2
  exit 1
fi

# Only re-register when the registration moved: a renamed bundle path, or a
# pre-v0.1 install whose login item was on under the old bundle id. On a plain
# reinstall the existing registration is still correct, so touching it would
# flip a user setting nobody asked us to flip.
if [ "$migrated" = 1 ] || [ "$legacy_login" = 1 ]; then
  echo "==> re-registering login item at $DEST"
  if ! "$DEST/Contents/MacOS/Tower" login-item on; then
    echo "   WARNING: re-register failed. Start-at-login is off or points at a bundle" >&2
    echo "   that no longer exists. Fix with the command below." >&2
  fi
fi

# A ~/.local/bin/tower link made for a pre-v0.1 build names the old executable,
# which this install just removed. Point it at the new one. The test suite sets
# TOWER_TEST_LINK; with TOWER_TEST_INSTALLED set and no link given, the real one
# is never touched.
if [ -n "${TOWER_TEST_INSTALLED:-}" ]; then
  LINK="${TOWER_TEST_LINK:-}"
else
  LINK="$HOME/.local/bin/tower"
fi
if [ -n "$LINK" ] && [ -L "$LINK" ]; then
  case "$(readlink "$LINK")" in
    */Tower.app/Contents/MacOS/HQClaudeLimits)
      ln -sf "$DEST/Contents/MacOS/Tower" "$LINK"
      echo "==> repointed $LINK at $DEST/Contents/MacOS/Tower"
      ;;
  esac
fi

echo ""
echo "Enable start-at-login with:"
echo "  \"$DEST/Contents/MacOS/Tower\" login-item on"
